INSERT INTO strategies VALUES(1,'viscale','viscale','{"rules":{"icpKeys":["B2B-1","B2B-2","B2B-3","B2C","UNI","BK"],"hashtags":["#viscale","#Vertriebssystem","#HubSpot","#Mittelstand"],"signoff":"das viscale-Team","editorialPlanTitle":"Redaktionsplan \u00b7 viscale","defaultOwner":"viscale","clusters":[{"key":"cluster_1","code":"E3-02","name":"Vertrieb h\u00e4ngt an Personen","match":"person|vertriebsleiter|kopf"},{"key":"cluster_2","code":"E3-01","name":"Blindflug im Forecast","match":"forecast|pipeline|signen|unterschreiben"},{"key":"cluster_3","code":"E3-03","name":"Leads versickern unbemerkt","match":"lead|versick|nachverfolg"},{"key":"cluster_4","code":"E3-05","name":"Wachstum wird teurer statt effizienter","match":"teuer|effizienz|cac|wachs"},{"key":"cluster_5","code":"E3-06","name":"Datenchaos & fehlende Datenhygiene","match":"daten|property|chaos|hygiene"},{"key":"cluster_6","code":"E1-02","name":"KI-Druck ohne Fundament","match":"ki|ai|breeze"}],"defaultClusterKey":"cluster_2","icpGuesser":[{"icp":"B2B-4","match":"cto|startup|scale|innovation|tech-talent"},{"icp":"B2B-5","match":"growth|saas|marketing|conversion|retention"}],"defaultIcp":"B2B-1","harvestCandidatePattern":"crm|forecast|lead|hubspot|pipeline","forbiddenPatterns":["!","beste[nrsm]?","einzigartig(?:e|er|es|en)?","revolution[a\u00e4]r(?:e|er|es|en)?","dein vertrieb kann mehr","verbessere deinen vertrieb"],"genericBkPatterns":["wir freuen uns","spannend(?:e|er|es|en)?","interessant(?:e|er|es|en)?","bucht jetzt","demo anfragen"],"toneLabel":"viscale-Tonalit\u00e4tsregeln","monitoring":{"gaps":["B2B-2 Forecast-Beweislast wird im Markt meist nur oberfl\u00e4chlich adressiert.","Niemand besetzt aktuell die Kombination aus HubSpot-Mechanismus und F\u00fchrungslogik konsequent."],"gapLine":"L\u00fccken f\u00fcr viscale herausarbeiten","toneGapHint":"Danach L\u00fccken gegen viscale-Tonalit\u00e4t spiegeln."},"bk":{"defaultTopic":"Property-Hygiene \u00b7 3 Fehler die wir oft sehen","preheader":"Konkrete Einordnung aus Delivery und ein n\u00e4chster Schritt in HubSpot.","mainCta":"Pr\u00fcft diese Woche eine aktive Pipeline auf fehlende Pflichtfelder und antwortet auf diese Mail, wenn ihr die Logik gemeinsam durchgehen wollt.","pathCheck":"Settings \u2192 Objects \u2192 Deals \u2192 Pipelines","topics":["Revenue Hub \u00b7 was sich f\u00fcr euch \u00e4ndert","Property-Hygiene \u00b7 3 Fehler die wir oft sehen","Renewal-Pipeline \u00b7 der untersch\u00e4tzte Hebel"]},"autoApproveScore":10,"mandatoryCta":"Mehr erfahren"}}','2026-09-01 10:17:37','2026-09-02 09:43:19');
INSERT INTO strategies VALUES(2,'vitalents','vitalents','{"rules":{"icpKeys":["B2B-1","B2B-2","B2B-3","B2C","UNI","BK"],"hashtags":["#vitalents","#Recruiting","#Klinik","#Pflege"],"signoff":"das vitalents-Team","editorialPlanTitle":"Redaktionsplan \u00b7 vitalents","defaultOwner":"vitalents","clusters":[{"key":"cluster_1","code":"V1-01","name":"Fachkr\u00e4ftemangel in Klinik und Pflege","match":"fachkr|pflege|klinik|personal"},{"key":"cluster_2","code":"V1-02","name":"Recruiting-Prozesse ohne System","match":"recruit|bewerb|prozess|system"},{"key":"cluster_3","code":"V1-03","name":"Kandidaten springen im Prozess ab","match":"kandidat|absprung|abbruch"},{"key":"cluster_4","code":"V1-04","name":"Employer Branding ohne Beweislast","match":"employer|brand|image"},{"key":"cluster_5","code":"V1-05","name":"Datenchaos im Bewerbermanagement","match":"daten|ats|chaos|hygiene"}],"defaultClusterKey":"cluster_1","icpGuesser":[{"icp":"BK","match":"bestand|renewal|adoption|retainer"},{"icp":"B2B-2","match":"klinik|pflege|recruiting|personal"}],"defaultIcp":"B2B-1","harvestCandidatePattern":"recruiting|pflege|klinik|kandidat|fachkr","forbiddenPatterns":["!","beste[nrsm]?","einzigartig(?:e|er|es|en)?","revolution[a\u00e4]r(?:e|er|es|en)?"],"genericBkPatterns":["wir freuen uns","spannend(?:e|er|es|en)?","interessant(?:e|er|es|en)?","bucht jetzt","demo anfragen"],"toneLabel":"vitalents-Tonalit\u00e4tsregeln","monitoring":{"gaps":["Recruiting-Prozesse werden im Markt selten mit Systemlogik adressiert.","Die Kombination aus Pflege-Fachkr\u00e4ftemangel und Prozesssteuerung ist kaum besetzt."],"gapLine":"L\u00fccken f\u00fcr vitalents herausarbeiten","toneGapHint":"Danach L\u00fccken gegen vitalents-Tonalit\u00e4t spiegeln."},"bk":{"defaultTopic":"Bewerber-Hygiene \u00b7 3 Fehler die wir oft sehen","preheader":"Konkrete Einordnung aus Delivery und ein n\u00e4chster Schritt im System.","mainCta":"Pr\u00fcft diese Woche einen aktiven Recruiting-Prozess und antwortet auf diese Mail, wenn ihr die Logik gemeinsam durchgehen wollt.","pathCheck":null,"topics":["Kandidaten-Kommunikation \u00b7 wo Prozesse brechen","Bewerber-Hygiene \u00b7 3 Fehler die wir oft sehen","Onboarding-Pipeline \u00b7 der untersch\u00e4tzte Hebel"]},"autoApproveScore":4}}','2026-09-01 10:17:37','2026-09-01 11:19:32');
