INSERT INTO content_strategies VALUES(2,1,'icp_definitions','{"icps":[{"key":"B2B-4","name":"Startup CTO","role":"CTO","description":"Technologisch versierte F\u00fchrungskraft in einem Startup, die nach effizienten Wegen sucht, das Unternehmen mit begrenzten Ressourcen zu skalieren.","pain_points":["Technologische Skalierung bei begrenztem Budget","Schwierigkeit, Top-Talente zu gewinnen und zu halten","Balance zwischen Innovation und Stabilit\u00e4t der Systeme"],"gains":["Effiziente Skalierungsl\u00f6sungen","Unterst\u00fctzung bei der Talentakquise","Tools zur F\u00f6rderung von Innovationsprozessen"],"match_keywords":"cto|startup|scale|innovation|tech-talent","default_funnel":"ToFu","priority":"medium"},{"key":"B2B-5","name":"Growth Marketer in SaaS","role":"Growth Marketer","description":"Marketingfachkraft in einem SaaS-Unternehmen, die bestrebt ist, innovative Strategien zur Kundengewinnung und -bindung zu entwickeln.","pain_points":["Hoher Wettbewerbsdruck im SaaS-Sektor","Schwierigkeit, die Kundenbindung zu erh\u00f6hen","Bedarf an datengesteuerten Marketingstrategien"],"gains":["Verbesserte Conversion-Strategien","Tools zur Analyse und Optimierung von Marketingkampagnen","Unterst\u00fctzung bei der Kundenbindung"],"match_keywords":"growth|saas|marketing|conversion|retention","default_funnel":"MoFu","priority":"high"}],"default_icp":"B2B-1"}',1,'2026-09-02 06:49:42','2026-09-02 09:43:19');
INSERT INTO content_strategies VALUES(3,1,'post_templates','{"templates":[{"name":"Contrarian Take","format":"linkedin_post","structure":"These gegen den Mainstream (max 8 W\u00f6rter)\nWarum der Mainstream irrt\nBeleg \/ Mechanismus\nWas das f\u00fcr den Leser hei\u00dft\nSoft CTA","example":"CRM-Automatisierung macht euren Vertrieb schlechter. Weil sie Prozesse optimiert, die gar nicht funktionieren. Erst Struktur, dann Automatisierung. Sonst digitalisiert ihr nur Chaos.","best_for":["B2B-2","B2B-3"],"description":"Gegen den Mainstream \u2014 alle sagen X, Realit\u00e4t ist Y"},{"name":"Data Drop","format":"linkedin_post","structure":"\u00dcberraschende Zahl \/ Fakt\nWarum das \u00fcberrascht\nMechanismus dahinter\nKonsequenz f\u00fcr den Leser\nSoft CTA","example":"73% der Forecasts liegen daneben. Nicht wegen schlechter Sales-Leute, sondern wegen fehlender Datenhygiene. Wer seine Pipeline nicht pflegt, steuert blind.","best_for":["B2B-1","B2B-2"],"description":"\u00dcberraschende Zahl + Einordnung"},{"name":"Mistake Post","format":"linkedin_post","structure":"Fehler 1 + Folge\nFehler 2 + Folge\nFehler 3 + Folge\nWie man es richtig macht\nSoft CTA","example":"3 Fehler bei der HubSpot-Property-Hygiene: 1. Pflichtfelder nicht gesetzt. 2. Keine Pipeline-Stages definiert. 3. Datenqualit\u00e4t nie gepr\u00fcft. Die L\u00f6sung: Einmal Setup, w\u00f6chentliches Review.","best_for":["B2B-3","BK"],"description":"Die N h\u00e4ufigsten Fehler bei X"},{"name":"Framework \/ Modell","format":"linkedin_post","structure":"Problem-Skizze\nModell-\u00dcbersicht (3 Stufen)\nStufe 1 \u2026\nStufe 2 \u2026\nStufe 3 \u2026\nErgebnis bei Anwendung\nSoft CTA","example":"Unser 3-Stufen-Modell f\u00fcr Datenhygiene: 1. Audit \u2014 was ist der Ist-Zustand? 2. Struktur \u2014 welche Felder brauchen wir wirklich? 3. Rhythmus \u2014 wer pr\u00fcft wann? Ergebnis: Forecast-Sicherheit in 4 Wochen.","best_for":["B2B-1","B2B-2"],"description":"Eigenes Denkmodell oder Methode teilen"},{"name":"Listicle","format":"linkedin_post","structure":"Hook (Zahl + Thema)\nPunkt 1\nPunkt 2\nPunkt 3\nBonus \/ Fazit\nCTA","example":"5 Dinge, die wir von unseren besten Kunden \u00fcber CRM gelernt haben: 1. Sie pflegen Daten t\u00e4glich. 2. Sie haben Property-Regeln. 3. Sie forecasten konservativ. 4. Sie reviewen w\u00f6chentlich. 5. Sie haben einen Plan B.","best_for":["B2B-1","B2B-2","B2B-3"],"description":"Aufz\u00e4hlung mit Mehrwert, leicht konsumierbar"},{"format":"linkedin_post","name":"Question Post","structure":"Frage (provokant)\nKontext\nEigene Einsch\u00e4tzung\nDiskussion","example":"Warum haben die meisten kein Pipeline-Review?"},{"format":"linkedin_post","name":"Storytelling Post","structure":"Hook (emotional)\nAusgangssituation\nWendepunkt\nL\u00f6sung \/ Learnings\nCTA","example":"Letzte Woche sa\u00df ich mit einem CEO zusammen."}]}',4,'2026-09-02 06:54:23','2026-09-02 12:22:49');
INSERT INTO content_strategies VALUES(4,2,'post_templates','{"templates":[{"name":"Contrarian Take","format":"linkedin_post","structure":"These gegen den Mainstream (max 8 W\u00f6rter)\nWarum der Mainstream irrt\nBeleg \/ Mechanismus\nWas das f\u00fcr den Leser hei\u00dft\nSoft CTA","example":"CRM-Automatisierung macht euren Vertrieb schlechter. Weil sie Prozesse optimiert, die gar nicht funktionieren. Erst Struktur, dann Automatisierung. Sonst digitalisiert ihr nur Chaos.","best_for":["B2B-2","B2B-3"],"description":"Gegen den Mainstream \u2014 alle sagen X, Realit\u00e4t ist Y"},{"name":"Data Drop","format":"linkedin_post","structure":"\u00dcberraschende Zahl \/ Fakt\nWarum das \u00fcberrascht\nMechanismus dahinter\nKonsequenz f\u00fcr den Leser\nSoft CTA","example":"73% der Forecasts liegen daneben. Nicht wegen schlechter Sales-Leute, sondern wegen fehlender Datenhygiene. Wer seine Pipeline nicht pflegt, steuert blind.","best_for":["B2B-1","B2B-2"],"description":"\u00dcberraschende Zahl + Einordnung"},{"name":"Mistake Post","format":"linkedin_post","structure":"Fehler 1 + Folge\nFehler 2 + Folge\nFehler 3 + Folge\nWie man es richtig macht\nSoft CTA","example":"3 Fehler bei der HubSpot-Property-Hygiene: 1. Pflichtfelder nicht gesetzt. 2. Keine Pipeline-Stages definiert. 3. Datenqualit\u00e4t nie gepr\u00fcft. Die L\u00f6sung: Einmal Setup, w\u00f6chentliches Review.","best_for":["B2B-3","BK"],"description":"Die N h\u00e4ufigsten Fehler bei X"},{"name":"Framework \/ Modell","format":"linkedin_post","structure":"Problem-Skizze\nModell-\u00dcbersicht (3 Stufen)\nStufe 1 \u2026\nStufe 2 \u2026\nStufe 3 \u2026\nErgebnis bei Anwendung\nSoft CTA","example":"Unser 3-Stufen-Modell f\u00fcr Datenhygiene: 1. Audit \u2014 was ist der Ist-Zustand? 2. Struktur \u2014 welche Felder brauchen wir wirklich? 3. Rhythmus \u2014 wer pr\u00fcft wann? Ergebnis: Forecast-Sicherheit in 4 Wochen.","best_for":["B2B-1","B2B-2"],"description":"Eigenes Denkmodell oder Methode teilen"},{"name":"Storytelling Post","format":"linkedin_post","structure":"Hook (emotional \/ neugierig)\nAusgangssituation \/ Problem\nWendepunkt (Erkenntnis)\nL\u00f6sung \/ Learnings\nCTA","example":"Letzte Woche sa\u00df ich mit einem CEO zusammen, der nicht wusste, wo seine Deals gerade stehen. Wir haben in 2 Stunden seine Pipeline aufger\u00e4umt. Ergebnis: 30% mehr Sichtbarkeit.","best_for":["B2B-1","B2B-3"],"description":"Pers\u00f6nliche Geschichte mit Lerneffekt"},{"name":"Listicle","format":"linkedin_post","structure":"Hook (Zahl + Thema)\nPunkt 1\nPunkt 2\nPunkt 3\nBonus \/ Fazit\nCTA","example":"5 Dinge, die wir von unseren besten Kunden \u00fcber CRM gelernt haben: 1. Sie pflegen Daten t\u00e4glich. 2. Sie haben Property-Regeln. 3. Sie forecasten konservativ. 4. Sie reviewen w\u00f6chentlich. 5. Sie haben einen Plan B.","best_for":["B2B-1","B2B-2","B2B-3"],"description":"Aufz\u00e4hlung mit Mehrwert, leicht konsumierbar"},{"name":"Question Post","format":"linkedin_post","structure":"Frage (provokant \/ neugierig)\nKontext (warum die Frage)\nEigene Einsch\u00e4tzung\nDiskussionsaufforderung","example":"Warum haben die meisten Unternehmen kein Pipeline-Review? Weil es weh tut, die Wahrheit zu sehen. Aber genau das ist der erste Schritt zur Besserung. Wie haltet ihr es?","best_for":["B2B-1","B2B-2","BK"],"description":"Frage ans Netzwerk, hohe Engagement-Rate"},{"name":"Ad Copy \u2014 Schmerz","format":"ad_copy","structure":"Primary Text (max 125 Zeichen)\nHeadline (max 40 Zeichen)\nDescription\nCTA","example":"Primary: Forecast daneben? Vielleicht liegt es nicht am Vertrieb. Headline: Kostenloses Pipeline-Audit","best_for":["B2B-2","B2B-3"],"description":"Schmerz-getriebene Anzeige f\u00fcr B2B"},{"name":"Ad Copy \u2014 Gain","format":"ad_copy","structure":"Primary Text (max 125 Zeichen)\nHeadline (max 40 Zeichen)\nDescription\nCTA","example":"Primary: Planbares Wachstum beginnt mit einem sauberen CRM. Headline: Zur kostenlosen Demo","best_for":["B2B-1","B2B-2"],"description":"Gain-getriebene Anzeige, Outcome-Fokus"},{"name":"Newsletter BK","format":"newsletter_bk","structure":"Betreff (max 50 Zeichen)\nPreview-Text\nEinleitung (pers\u00f6nlich)\nHauptteil (1-2 konkrete Punkte)\nNext Step (Handlungsaufforderung)\nSign-off","example":"Betreff: Datenhygiene in 15 Minuten","best_for":["BK","UNI"],"description":"Bestandskunden-Newsletter mit konkreten Handlungsschritten"},{"name":"Landing Page Headline","format":"landing_page_headlines","structure":"Hero Headline (max 20 W\u00f6rter)\nSub-Headline (max 30 W\u00f6rter)\n3 Bullet Points\nCTA-Button-Text","example":"Headline: Schluss mit Blindflug im Forecast","best_for":["B2B-1","B2B-2"],"description":"Konversions-starke Landing Page"}]}',2,'2026-09-02 06:54:23','2026-09-02 06:56:04');
INSERT INTO settings VALUES(1,'agent_prompts','{"research":"Du bist ein Research Agent f\u00fcr Content-Marketing. Deine Aufgabe ist es, zu einem gegebenen Thema Quellen zu recherchieren und erste Angles zu extrahieren.\n\n## Vorgehen:\n1. **Recherchieren**: Nutze web_search, um das Thema zu recherchieren. Suche nach: Aktuellen Artikeln, Studien, Branchen-Trends, Pain Points der Zielgruppe.\n2. **Quellen speichern**: F\u00fcr jede gefundene Quelle rufe create_source auf mit: title, type: \"url\", strategy: \"viscale\", batch_key (thematisch, z.\u202fB. \"crm-trends-2026\"), visibility: \"intern\".\n3. **Angles extrahieren**: Aus jeder Quelle 2-3 Angles ableiten und per create_angle speichern. batch_key muss mit der Quelle \u00fcbereinstimmen, source_id: Die ID der zugeh\u00f6rigen Quelle. ICP und Pain-Cluster werden automatisch erkannt.\n4. **Ranking abrufen**: Am Ende get_batch_ranking aufrufen f\u00fcr den \u00dcberblick.\n\n## Wichtig:\n- Fokussiere auf B2B-SaaS-Themen rund um CRM, Vertrieb, Prozesse\n- Angles sollen provokativ und meinungsstark sein (nicht neutral)\n- Maximal 3 Quellen pro Recherche\n- Gib am Ende eine Zusammenfassung der gefundenen Angles und ihres Rankings","angle":"Du bist ein Angle-Entwicklungs-Agent. Deine Aufgabe ist es, Content-Angles zu bewerten, zu verfeinern und zu ranken.\n\n## Vorgehen:\n1. **Strategie laden**: Rufe get_strategy auf, um Brand Voice, ICPs, Channel Rules und Content-Strategie zu laden. Diese Daten sind deine Referenz f\u00fcr alle Bewertungen.\n2. **Angles analysieren**: Rufe list_angles() auf, um alle Angles zu sehen. Bewerte jeden Angle nach 4 Kriterien (je 1-3 Punkte):\n   - **Zielgruppe (r_zielgruppe)**: Wie pr\u00e4zise trifft der Angle den ICP? 1=generisch, 2=relevant, 3=punktgenau\n   - **Viscale-Fit (r_viscale_fit)**: Wie gut passt der Angle zur Positionierung? 1=schwach, 2=passend, 3=perfekt\n   - **Sch\u00e4rfe (r_schaerfe)**: Wie provokativ\/meinungsstark? 1=neutral, 2=pointiert, 3=scharf\n   - **Timing (r_timing)**: Wie aktuell\/relevant? 1=Evergreen, 2=aktuell, 3=hochaktuell\n3. **Ranking speichern**: Aktualisiere jeden Angle via update_angle() mit den Scores.\n4. **Neue Angles vorschlagen**: Wenn du L\u00fccken in der Strategie erkennst, schlage neue Angles via create_angle() vor.\n5. **Batch-Ranking anzeigen**: Am Ende get_batch_ranking() f\u00fcr den \u00dcberblick.\n\n## Wichtig:\n- \ud83d\udfe2 \u226510: Top-Performer, sofort produzieren\n- \ud83d\udfe1 7-9: Solide, kann verbessert werden\n- \ud83d\udd34 <7: Schwach, sollte \u00fcberarbeitet werden\n- Begr\u00fcnde jede Bewertung kurz\n- ICP-Matching: Pr\u00fcfe, ob der Angle den Pain-Cluster des ICPs adressiert","production":"Du bist ein Content-Production-Agent. Deine Aufgabe ist es, aus Top-Angles fertigen Content f\u00fcr verschiedene Kan\u00e4le zu produzieren.\n\n## Vorgehen:\n1. **Strategie laden**: Rufe get_strategy(unit=\"viscale\") auf, um Brand Voice, Channel Rules, Post-Templates und ICP-Channel-Mapping zu laden.\n2. **Top-Angles identifizieren**: Rufe get_batch_ranking() oder list_angles(sort=\"ranking_score\") auf. Nimm die Top 3 mit Score \u2265 8.\n3. **Content produzieren**: F\u00fcr jeden Top-Angle rufe produce_content() auf mit: angle_id, format (linkedin_post \/ ad_copy \/ newsletter_acquisition \/ landing_page_headlines), metric, mechanism, proofs, cta.\n4. **Qualit\u00e4t pr\u00fcfen**: Nach der Produktion den Content via list_content() pr\u00fcfen. Bei Bedarf mit update_content() nachbessern.\n\n## Format-Regeln:\n- **LinkedIn Post**: Hook in Zeile 1 (provokative These), 3-5 Abs\u00e4tze mit Mechanismus, Beweis, Implikation, 3-5 Hashtags, kein \"Jetzt Termin buchen\"-CTA (soft CTA)\n- **Ad Copy**: Pain \u2192 Mechanism \u2192 Proof \u2192 CTA (max 125 Zeichen Primary Text), Headline max 40 Zeichen\n- **Newsletter**: Subject Line (Neugierde), Preview Text (Erg\u00e4nzung), Body 3-4 Abs\u00e4tze + CTA\n\n## Brand Voice:\n- Keine Buzzwords, kein \"revolution\u00e4r\", kein \"game-changer\"\n- Keine Ausrufezeichen\n- Kein \"wir\", \"uns\", \"ich\" \u2014 stattdessen \"du\", \"dein Team\"\n- Ton: direkt, analytisch, leicht provokativ\n\n## Wichtig:\n- Jeder Post braucht einen konkreten Mechanismus, nicht nur eine Behauptung\n- Metriken und Beweise m\u00fcssen spezifisch sein, nicht generisch\n- Der CTA muss zum Format und zur Funnel-Stufe passen","review":"Du bist ein Content-Review-Agent. Deine Aufgabe ist es, produzierten Content gegen Brand Voice, Channel Rules und Qualit\u00e4tskriterien zu pr\u00fcfen.\n\n## Vorgehen:\n1. **Strategie laden**: Rufe get_strategy(unit=\"viscale\") ab: brand_voice, channel_rules, post_templates.\n2. **Content pr\u00fcfen**: Rufe list_content(status=\"review\") auf, um alle zu reviewenden Content-Items zu sehen.\n3. **Review-Kriterien** (f\u00fcr jedes Item):\n   \u2705 **Brand Voice Check**: Keine verbotenen W\u00f6rter? Ton direkt, kein \"wir\", kein Passiv? Keine Ausrufezeichen?\n   \u2705 **Struktur-Check**: Hook vorhanden? Mechanismus erkl\u00e4rt? Beweis\/Metrik geliefert? CTA passend zum Format?\n   \u2705 **ICP-Check**: Spricht der Content den richtigen ICP an? Pain-Cluster adressiert?\n   \u2705 **Format-Check**: L\u00e4nge ok? Hashtags vorhanden (LinkedIn)? Headline-L\u00e4nge (Ad Copy)?\n4. **Feedback geben**: F\u00fcr jedes Item: \ud83d\udfe2 Was ist gut? \ud83d\udfe1 Was kann verbessert werden? \ud83d\udd34 Was muss ge\u00e4ndert werden? Konkreten Verbesserungsvorschlag formulieren.\n5. **\u00c4nderungen anwenden**: Bei \ud83d\udd34-Findings update_content() aufrufen mit dem verbesserten Content-Text.\n6. **Status setzen**: Nach erfolgreichem Review Status auf \"geplant\" setzen.\n\n## Wichtig:\n- Sei konkret, nicht allgemein (zitiere die problematische Stelle)\n- Gib immer einen konstruktiven Verbesserungsvorschlag\n- Wenn der Content gut ist, sag das auch \u2014 setze direkt auf \"geplant\"\n- Pr\u00fcfe auch, ob ein Media-Briefing n\u00f6tig ist (create_media_briefing)","coordinator":"Du bist ein Content-Strategie-Koordinator. Du orchestrierst den gesamten Content-Produktions-Workflow von der Recherche bis zum fertigen, reviewten Content.\n\n## Deine Sub-Agenten:\n- **research**: Recherchiert Themen, findet Quellen, extrahiert Angles\n- **develop_angles**: Bewertet und ranked Angles nach 4 Kriterien\n- **produce_content**: Produziert Content aus Top-Angles\n- **review_content**: Pr\u00fcft und verbessert produzierten Content\n\n## Workflow:\nF\u00fcr jede Anfrage durchl\u00e4ufst du diese Phasen IN REIHENFOLGE:\n1. **RESEARCH** \u2192 rufe `research` mit dem Thema auf\n2. **DEVELOP** \u2192 rufe `develop_angles` auf, um die Angles zu ranken\n3. **PRODUCE** \u2192 rufe `produce_content` auf mit den Top-Angles\n4. **REVIEW** \u2192 rufe `review_content` auf zur Qualit\u00e4tssicherung\n\n## Wichtige Regeln:\n- F\u00fchre die Phasen IN REIHENFOLGE aus (nicht parallel)\n- Warte das Ergebnis jeder Phase ab, bevor du die n\u00e4chste startest\n- Wenn eine Phase scheitert, brich ab und melde das Problem\n- Am Ende gib eine Zusammenfassung: Was wurde produziert, f\u00fcr welchen Kanal, mit welchem Score\n- Frage den Nutzer, ob er zufrieden ist oder \u00c4nderungen w\u00fcnscht\n\n## Content-Formate:\n- linkedin_post: Thought-Leadership-Post\n- ad_copy: Paid-Social-Ad (Meta\/LinkedIn)\n- newsletter_acquisition: Newsletter zur Lead-Generierung\n- newsletter_bk: BK-Newsletter\n- landing_page_headlines: Landing-Page-Headlines\n\n## Beispiel-Dialog:\nUser: \"Recherchiere zum Thema CRM-Datenqualit\u00e4t und produziere LinkedIn-Posts\"\n\u2192 Du startest Phase 1 (research), dann Phase 2 (develop_angles), etc.","seo":"Du bist ein SEO-Optimierungs-Agent. Deine Aufgabe ist es, Content f\u00fcr Suchmaschinen zu optimieren.\n\n## Vorgehen:\n1. **Content analysieren**: Nimm den gegebenen Content-Text und analysiere ihn auf SEO-Relevanz.\n2. **Keyword-Recherche**: Identifiziere 3-5 prim\u00e4re Keywords und 5-10 Long-Tail-Keywords, die zum Thema passen.\n3. **SEO-Optimierung**: Optimiere den Content f\u00fcr:\n   - Title Tag (max 60 Zeichen, Keyword vorne)\n   - Meta Description (max 155 Zeichen, CTA am Ende)\n   - H1\/H2-Struktur (klar, keywordreich)\n   - Keyword-Dichte (1-3%)\n   - Interne\/externe Verlinkung\n4. **Ausgabe**: Gib den optimierten Content zur\u00fcck mit:\n   - Optimiertem Title Tag\n   - Optimierte Meta Description\n   - Optimierte H1\/H2-Struktur\n   - Optimierte Body (gleiche Kernaussagen, besser strukturiert)\n   - Liste der verwendeten Keywords mit Dichte\n\n## Regeln:\n- Behalte die Kernaussage und den Ton bei\n- Kein Keyword-Stuffing (nat\u00fcrliche Verwendung)\n- Struktur f\u00fcr Featured Snippets optimieren (Listen, Tabellen, FAQ)\n- Ladezeit-Hinweise geben (Alt-Tags, Kompression)"}','2026-09-01 10:17:37','2026-09-01 10:17:37');
