/* WARNING: Script requires that SQLITE_DBCONFIG_DEFENSIVE be disabled */
PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "strategies" ("id" integer primary key autoincrement not null, "key" varchar not null, "name" varchar not null, "config" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "sources" ("id" varchar not null, "strategy_id" integer not null, "title" varchar not null, "type" varchar check ("type" in ('pdf', 'url', 'interview', 'intern', 'research')) not null, "visibility" varchar not null default 'intern', "file_ref" varchar, "batch_key" varchar, "created_at" datetime, "updated_at" datetime, "url" varchar, "monitor" tinyint(1) not null default '0', "frequency" varchar not null default 'weekly', "last_checked_at" datetime, "content_hash" varchar, "last_content_preview" varchar, foreign key("strategy_id") references "strategies"("id") on delete cascade, primary key ("id"));
CREATE TABLE IF NOT EXISTS "content_strategies" ("id" integer primary key autoincrement not null, "strategy_id" integer not null, "key" varchar not null, "content" text not null, "version" integer not null default '1', "created_at" datetime, "updated_at" datetime, foreign key("strategy_id") references "strategies"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "settings" ("id" integer primary key autoincrement not null, "key" varchar not null, "value" text not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "agent_logs" ("id" integer primary key autoincrement not null, "agent" varchar not null, "provider" varchar not null, "model" varchar not null, "input" text not null, "output" text not null, "status" varchar not null default 'success', "tokens_used" integer, "duration_ms" integer, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "monitoring_events" ("id" integer primary key autoincrement not null, "type" varchar not null, "status" varchar not null default 'success', "url" varchar, "query" varchar, "provider" varchar, "model" varchar, "credits" numeric, "input" text, "payload" text, "duration_ms" integer, "error" varchar, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "angles" ("id" varchar not null, "source_id" varchar, "strategy_id" integer not null, "batch_key" varchar, "angle" text not null, "icp" varchar, "pain_cluster" varchar, "statement_type" varchar, "funnel" varchar, "viscale_phase" varchar, "r_zielgruppe" integer, "r_viscale_fit" integer, "r_schaerfe" integer, "r_timing" integer, "ranking_score" integer, "ranking_rang" integer, "status" varchar not null default ('neu'), "created_at" datetime, "updated_at" datetime, "embedding" text, "score_reasoning" text, "duplicate_of_id" varchar, "similarity_score" float, foreign key("strategy_id") references strategies("id") on delete cascade on update no action, foreign key("source_id") references sources("id") on delete set null on update no action, foreign key("duplicate_of_id") references "angles"("id") on delete set null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "personas" ("id" integer primary key autoincrement not null, "strategy_id" varchar, "name" varchar not null, "role" varchar, "voice" text, "cadence" varchar, "active" tinyint(1) not null default ('1'), "created_at" datetime, "updated_at" datetime, "core_statements" text, "tonality" text, "positioning" varchar, "channel_strategies" text, "content_attributes" text, "forbidden_words" text, "max_sentence_length" integer, "emoji_usage" varchar not null default ('none'), "perspective" varchar not null default ('ich'), foreign key("strategy_id") references strategies("id") on delete cascade on update no action);
CREATE TABLE IF NOT EXISTS "persona_strategy_map" ("id" integer primary key autoincrement not null, "persona_id" integer not null, "strategy_id" integer not null, "mapped_angles" text, "mapped_topics" text, "is_default" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("persona_id") references "personas"("id") on delete cascade, foreign key("strategy_id") references "strategies"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "persona_examples" ("id" integer primary key autoincrement not null, "persona_id" integer not null, "strategy_id" integer not null, "format" varchar not null, "content" text not null, "why_good" text, "active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime, foreign key("persona_id") references "personas"("id") on delete cascade, foreign key("strategy_id") references "strategies"("id") on delete cascade);
COMMIT;
